// reconstruction.go - ReconstructDataColumnSidecars
func ReconstructDataColumnSidecars(verifiedRoSidecars []blocks.VerifiedRODataColumn) ([]blocks.VerifiedRODataColumn, error) {
    if len(verifiedRoSidecars) == 0 { return nil, ErrNotEnoughDataColumnSidecars }
    referenceSidecar := verifiedRoSidecars[0]
    blobCount := len(referenceSidecar.Column)
    blockRoot := referenceSidecar.BlockRoot()
    // Check all columns same length and same block root
    for _, sidecar := range verifiedRoSidecars[1:] {
        if len(sidecar.Column) != blobCount { return nil, ErrColumnLengthsDiffer }
        if sidecar.BlockRoot() != blockRoot { return nil, ErrBlockRootMismatch }
    }
    // Deduplicate by column index (map key = Index)
    sidecarByIndex := make(map[uint64]blocks.VerifiedRODataColumn, len(verifiedRoSidecars))
    for _, inVerifiedRoSidecar := range verifiedRoSidecars {
        sidecarByIndex[inVerifiedRoSidecar.Index] = inVerifiedRoSidecar
    }
    // 50% threshold check
    sidecarCount := len(sidecarByIndex)
    if uint64(sidecarCount) < MinimumColumnCountToReconstruct() { return nil, ErrNotEnoughDataColumnSidecars }
    // Recover in parallel per blob
    var wg errgroup.Group
    cellsAndProofs := make([]kzg.CellsAndProofs, blobCount)
    for blobIndex := range uint64(blobCount) {
        wg.Go(func() error {
            cellsIndices := make([]uint64, 0, sidecarCount)
            cells := make([]kzg.Cell, 0, sidecarCount)
            for columnIndex, sidecar := range sidecarByIndex {
                cell := sidecar.Column[blobIndex]
                cells = append(cells, kzg.Cell(cell))
                cellsIndices = append(cellsIndices, columnIndex)
            }
            cellsAndProofsForBlob, err := kzg.RecoverCellsAndKZGProofs(cellsIndices, cells)
            if err != nil { return errors.Wrapf(err, ...) }
            cellsAndProofs[blobIndex] = cellsAndProofsForBlob
            return nil
        })
    }
    if err := wg.Wait(); err != nil { return nil, errors.Wrap(err, ...) }
    // Construct reconstructed sidecars (the KZG proofs come from c-kzg-4844 library)
    reconstructedSidecars, err := dataColumnsSidecars(...)
    // IMPORTANT: reconstructed sidecars are marked as "verified" without re-verifying KZG proofs
    reconstructedVerifiedRoSidecars := make([]blocks.VerifiedRODataColumn, 0, ...)
    for _, sidecar := range reconstructedSidecars {
        roSidecar, err := blocks.NewRODataColumnWithRoot(sidecar, blockRoot)
        verifiedRoSidecar := blocks.NewVerifiedRODataColumn(roSidecar) // marked verified!
        reconstructedVerifiedRoSidecars = append(reconstructedVerifiedRoSidecars, verifiedRoSidecar)
